# Mathematics and counting: PC pages for HOW BIG IS IT? (see README.md). Values are worked out by code.
from helpers import *
import sys
if hasattr(sys, "set_int_max_str_digits"): sys.set_int_max_str_digits(0)
F = math.factorial

def _atan_inv(x, one):
    total = term = one // x; x2 = x * x; k = 1; sign = 1
    while term:
        term //= x2; k += 2; sign = -sign; total += sign * (term // k)
    return total
def pi_digits(n):                                   # first n digits of pi as a string, 3141...
    one = 10 ** (n + 12)
    p = 4 * (4 * _atan_inv(5, one) - _atan_inv(239, one))
    return str(p // 10 ** 12)[:n]
def e_digits(n):                                    # first n digits of e, 2718...
    one = 10 ** (n + 12); total = term = one; k = 1
    while term:
        term //= k; total += term; k += 1
    return str(total // 10 ** 12)[:n]
def sqrt2_digits(n): return str(math.isqrt(2 * 10 ** (2 * (n - 1))))
def phi_digits(n): return str((math.isqrt(5 * 10 ** (2 * (n - 1))) + 10 ** (n - 1)) // 2)
def rubik(n):                                       # positions of the n x n x n cube
    w = (n - 2) // 2; c = (n - 2) ** 2 // 4
    v = F(8) * 3 ** 7 * (F(12) * 2 ** 10 if n % 2 else 1) * F(24) ** w * (F(24) // (24 ** 6)) ** c
    return v // 24 if n % 2 == 0 else v
def collatz_steps(n):
    s = 0
    while n != 1: n = n // 2 if n % 2 == 0 else 3 * n + 1; s += 1
    return s
def digit_count_pow2m1(p): 
    from decimal import Decimal, getcontext
    getcontext().prec = 40
    return int(Decimal(p) * Decimal(2).log10()) + 1

